  AND ph.tenant_id = #{tenantId, jdbcType=BIGINT}
  AND ph.use_at = 'Y'

SELECT 

WHERE ph.sales_delivery_plan_id = #{salesDeliveryPlanId, jdbcType=BIGINT}
  AND ph.tenant_id = #{tenantId, jdbcType=BIGINT}
  AND ph.use_at = 'Y'
FOR UPDATE OF ph

SELECT h.sales_order_id AS salesOrderId, od.sales_order_detail_id AS salesOrderDetailId, h.order_no AS orderNo, h.order_dt AS orderDt, h.customer_id AS customerId, c.customer_code AS customerCode, c.customer_name AS customerName, h.delivery_place AS deliveryPlace, h.delivery_method AS deliveryMethod, COALESCE(od.delivery_dt, h.delivery_dt) AS planDt, od.line_no AS lineNo, od.material_id AS materialId, m.material_code AS materialCode, m.material_name AS materialName, m.unit AS unit, od.order_qty AS orderQty, COALESCE(od.shipped_qty, 0) AS shippedQty, od.order_qty - COALESCE(od.shipped_qty, 0) AS remainingQty, od.unit_price AS unitPrice FROM tb_sales_order_hd h JOIN tb_sales_order_dt od ON od.sales_order_id = h.sales_order_id AND od.tenant_id = h.tenant_id JOIN tb_customer_info c ON c.customer_id = h.customer_id AND c.tenant_id = h.tenant_id AND c.use_at = 'Y' JOIN tb_material_info m ON m.material_id = od.material_id AND m.tenant_id = od.tenant_id AND m.delete_status = 'N' AND m.deleted_at IS NULL WHERE h.tenant_id = #{tenantId, jdbcType=BIGINT} AND h.use_at = 'Y' AND h.status = '수주등록' AND NOT EXISTS ( SELECT 1 FROM tb_sales_delivery_plan_hd ph WHERE ph.sales_order_id = h.sales_order_id AND ph.tenant_id = h.tenant_id AND ph.use_at = 'Y' )
AND (h.order_no ILIKE '%' || #{keyword} || '%' OR c.customer_code ILIKE '%' || #{keyword} || '%' OR c.customer_name ILIKE '%' || #{keyword} || '%')
ORDER BY h.order_dt DESC, h.sales_order_id DESC, od.line_no LIMIT #{limit, jdbcType=INTEGER}

INSERT INTO tb_sales_delivery_plan_hd (
    tenant_id, sales_order_id, plan_no, created_by
) VALUES (
    #{tenantId, jdbcType=BIGINT}, #{salesOrderId, jdbcType=BIGINT},
    #{planNo, jdbcType=VARCHAR}, #{createdBy, jdbcType=VARCHAR}
)
RETURNING sales_delivery_plan_id

mapper.update:
UPDATE tb_sales_delivery_plan_dt
SET material_id = #{materialId, jdbcType=BIGINT},
    line_no = #{lineNo, jdbcType=INTEGER},
    plan_dt = #{planDt, jdbcType=DATE},
    planned_qty = #{plannedQty, jdbcType=NUMERIC},
    updated_by = #{updatedBy, jdbcType=VARCHAR},
    updated_at = CURRENT_TIMESTAMP
WHERE sales_delivery_plan_detail_id = #{salesDeliveryPlanDetailId, jdbcType=BIGINT}
  AND sales_delivery_plan_id = #{salesDeliveryPlanId, jdbcType=BIGINT}
  AND tenant_id = #{tenantId, jdbcType=BIGINT}
  AND delivered_qty = #{deliveredQty, jdbcType=NUMERIC}

mapper.delete:
DELETE FROM tb_sales_delivery_plan_dt
WHERE sales_delivery_plan_detail_id = #{salesDeliveryPlanDetailId, jdbcType=BIGINT}
  AND sales_delivery_plan_id = #{salesDeliveryPlanId, jdbcType=BIGINT}
  AND tenant_id = #{tenantId, jdbcType=BIGINT}
  AND NOT EXISTS (
      SELECT 1
      FROM tb_sales_delivery_dt dd
      WHERE dd.sales_delivery_plan_detail_id = tb_sales_delivery_plan_dt.sales_delivery_plan_detail_id
        AND dd.tenant_id = tb_sales_delivery_plan_dt.tenant_id
  )

