SELECT COUNT(*)
FROM tb_sales_delivery_dt dd
WHERE dd.sales_delivery_plan_detail_id = #{salesDeliveryPlanDetailId, jdbcType=BIGINT}
  AND dd.tenant_id = #{tenantId, jdbcType=BIGINT}

SELECT
LEFT JOIN tb_sales_delivery_plan_dt pd ON pd.sales_delivery_plan_id = ph.sales_delivery_plan_id AND pd.tenant_id = ph.tenant_id WHERE ph.tenant_id = #{tenantId, jdbcType=BIGINT} AND ph.use_at = 'Y'
AND pd.plan_dt >= #{planDtFrom, jdbcType=DATE}
AND pd.plan_dt <= #{planDtTo, jdbcType=DATE}
AND (ph.plan_no ILIKE '%' || #{keyword} || '%' OR oh.order_no ILIKE '%' || #{keyword} || '%' OR c.customer_code ILIKE '%' || #{keyword} || '%' OR c.customer_name ILIKE '%' || #{keyword} || '%')
GROUP BY ph.sales_delivery_plan_id, oh.order_no, oh.order_dt, oh.customer_id, c.customer_code, c.customer_name ORDER BY oh.order_dt DESC, ph.sales_delivery_plan_id DESC
